 {
  "id": "2113680701770068067-1",
  "text": "Kimi K3.1 Pro built a mythical Eastern celestial palace in Unreal Engine 5.8, featuring a 36-bay colonnade with a radius of 1,750 meters and a colossal dragon procedurally modeled in Blender. The main character was created using MetaHuman. The scene contains 36 million source triangles and uses Nanite for rendering and Lumen for lighting.\nExternal assets used: Cloud Forge VDB Clouds, Poly Haven/ambientCG 8K materials, and NASA LRO/LOLA moon data.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-2",
  "text": "Kimi K3.1 Pro created an Eastern ancient-themed 3D RPG preview video in Unreal Engine 5.8, featuring a swordsman flying through a sea of clouds, past floating islands, and into a classical city above the clouds.\nConcept design and part of the asset inspiration come from Rednote creator @-Duduu-.\nExternal assets used: the Gandhara Buddha and Water-Moon Guanyin 3D scans (Minneapolis Institute of Art, CC0).",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-3",
  "text": "Kimi K3.1 Pro built a stylized 3D action-adventure game using Godot 4.7.2. The project features five explorable regions with procedural terrain, roads, water, vegetation, and village layouts, alongside third-person combat, a two-phase Boss fight, gathering, a day–night cycle, and campfire fast travel.\nExternal assets used: Quaternius Stylized Nature MegaKit, Quaternius Medieval Village MegaKit, Kenney Survival Kit, Quaternius Ultimate Monsters, KayKit Character Pack, KayKit Character Animations 1.1, Quaternius Universal Animation Library, CDmir Goblin, rubberduck Vampire Bat, and the Fredoka, ZCOOL KuaiLe, and LXGW WenKai fonts.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-4",
  "text": "Kimi K3.1 Pro built an airport's indoor rainforest valley in Blender, producing a 19.5-second, 1920×1080, 60 fps modeling showcase video.\nTools used: Blender, Python, Geometry Nodes, Cycles, Pillow, NumPy, and FFmpeg.\nExternal assets used: \"Kloofendal 48d Partly Cloudy (Pure Sky)\" 4K HDRI from Poly Haven, by Greg Zaal and Jarod Guest, CC0 licensed, used for sky lighting and environment reflections.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-5",
  "text": "Kimi K3.1 Pro used Python to build a detailed turbofan model in FreeCAD, covering the fan, reduction gearbox, compressors, combustor, turbines, and external piping across 2,100 solids. The project supports step-by-step assembly, an exploded internal view, and rotational animation demonstrating the fan, low-pressure spool, and high-pressure spool at 2,780, 8,590, and 12,400 RPM respectively.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-6",
  "text": "Using trimesh, Kimi K3.1 Pro created a five-part, 3D-printable table lamp inspired by Fujian tulou, reimagining its distinctive circular architecture as an intricate openwork lattice.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-7",
  "text": "Kimi K3.1 Pro built an interactive, browser-based 3D experience in Blender, creating a cathedral's interior with roughly 3.3 million triangles and animating 8,368 components, with ribbed vaults, stone sculptures, and vivid stained-glass lighting.\nExternal assets used: stone textures from Poly Haven (CC0) and Mylius's stained-glass photograph (CC BY-SA 3.0).",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 },
 {
  "id": "2113680701770068067-8",
  "text": "Kimi K3.1 Pro created a cinematic robot animation set in a post-apocalyptic city using Blender 5.2 and Python/bpy, featuring expressive character animation, a weathered metal workshop, ruined surroundings, and procedural dust, debris, and dusk effects. Cycles GPU handled rendering, and FFmpeg handled video encoding and audio mixing.\nExternal assets used: CC0 props, rocks, textures and HDRI skies from Poly Haven, plus PBR textures from ambientCG.",
  "source": "https://www.kimi.ai/blog/kimi-k3-1-pro"
 }
]

